import { test, expect } from '@playwright/test';

test.describe('Image Upload - Small Dimensions Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display error when image dimensions are too small for upload', async ({ page }) => {
    // Setup: intercept the upload API
    await page.route('**/api/upload', (route) => {
      route.abort('blockedbyclient');
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/small-image.png');

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is visible and contains expected text
    const errorMessage = page.getByText(/image dimensions must be at least 100x100 pixels/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message has error styling
    const errorContainer = page.locator('[data-testid="error-message"]');
    await expect(errorContainer).toHaveClass(/error-message/);

    // Verify upload button is still enabled
    await expect(uploadButton).toBeEnabled();
  });

  test('should allow upload when image dimensions meet minimum requirements', async ({ page }) => {
    // Setup: intercept the upload API
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload Image');
    await fileInput.setInputFiles('playwright/fixtures/large-image.png');

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for success response
    await page.waitForTimeout(500);

    // Verify success message is displayed
    const successMessage = page.getByText(/image uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify error message does not exist
    const errorMessage = page.getByText(/image dimensions must be at least 100x100 pixels/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify success indicator is visible
    const successIndicator = page.locator('[data-testid="success-indicator"]');
    await expect(successIndicator).toBeVisible();
  });
});
